 bx.set(ylabel='Equal-class mean WAPE (%) — lower is better',title='Both road classes receive equal weight');bx.legend(fontsize=8,frameon=False);bx.grid(alpha=.15);fig.tight_layout(rect=[0,.2,1,1]);fig.text(.5,.035,'Distinct 64-bit physical-arc path fingerprints are a diversity diagnostic, not proof of disjoint routes or independent fallback capacity.\nRepeated routes keep their 1/3 realization weight. The equal-class score is an uncalibrated development summary,not a release gate.\nJoint improvement separately requires neither class WAPE to worsen relative to T2 in either development group.',ha='center',fontsize=8);fig.savefig(R/'choice_diversity_scores.png',dpi=170);plt.close(fig)
