 gates={x['arm']:x['joint_development_improvement_vs_T2']for x in s['joint_development_gates']};passed=[CN[a]for a in ARMS[1:]if gates[a]];gatephrase='、'.join(passed)if passed else'无分支';result='速度口径修正及其多路径分支仅小幅改善两类道路，普通道路仍严重低估。'if passed else'本次没有分支在两组开发资料中同时改善两类道路。';rows=''
